-- ================================================================================================
-- Espacios Abiertos e Islas del Mar Menor · N2 completo: espacio, hábitats, especies y vínculos.
--
-- GENERADO por Tools/catalogo-nacional/build-park-sql.js desde Frontend\Data\parks\murcia\espacios-abiertos-e-islas-del-mar-menor\park.json
-- y Data/parks/murcia/espacios-abiertos-e-islas-del-mar-menor/geo/habitats.geojson. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-park-sql.js --park espacios-abiertos-e-islas-del-mar-menor
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado:
-- con backend desplegado, un espacio que no esté en la base de datos no existe para el usuario.
--
-- Contenido: 1 espacio · 19 hábitats · 250 especies · 343 vínculos especie↔hábitat.
-- Los puntos de interés van aparte, en `n3-pois-<slug>.sql` (build-poi-sql.js).
--
-- ORDEN: la fila de `parks` va PRIMERO y no es opcional. Sin ella los INSERT ... SELECT de
-- abajo no encuentran nada y cargan CERO filas sin dar ningún error.
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre las claves únicas del esquema. Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database\espacios-abiertos-e-islas-del-mar-menor-n2.sql
-- ================================================================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------------------------------------------
-- 1. El espacio. Sin esta fila, TODO lo demás carga cero filas en silencio.
-- ------------------------------------------------------------------------------------------------
INSERT INTO parks (slug, name, category, region, province, municipality, description, latitude, longitude, status)
VALUES ('espacios-abiertos-e-islas-del-mar-menor', 'Espacios Abiertos e Islas del Mar Menor', 'Paisaje Protegido', 'Región de Murcia', 'Murcia', 'Cartagena y Los Alcázares y San Javier', 'Las islas volcánicas del Mar Menor y los saladares libres de su orilla: humedales salinos que dan refugio a las aves entre tanta costa urbanizada.', 37.69623, -0.84113, 'available')
ON DUPLICATE KEY UPDATE
    name = VALUES(name), category = VALUES(category), region = VALUES(region),
    province = VALUES(province), municipality = VALUES(municipality),
    description = VALUES(description), latitude = VALUES(latitude),
    longitude = VALUES(longitude), status = VALUES(status);

-- ------------------------------------------------------------------------------------------------
-- 2. Hábitats (19). `geometry` sale del geojson; sin ella el mapa dibuja un círculo.
-- ------------------------------------------------------------------------------------------------
INSERT INTO habitats (park_id, slug, code, name, habitat_type, description, is_priority, latitude, longitude, color, geometry, review_note, hic_subtipos, fitosociologia, origen, fuentes, solo_curada, audio_url, audio_transcript, image_url, image_attribution, image_note)
SELECT pk.id, h.slug, h.code, h.name, h.habitat_type, h.description, h.is_priority, h.latitude, h.longitude, h.color, h.geometry, h.review_note, h.hic_subtipos, h.fitosociologia, h.origen, h.fuentes, h.solo_curada, h.audio_url, h.audio_transcript, h.image_url, h.image_attribution, h.image_note
FROM parks pk JOIN (
