    SELECT 'dunas-con-vegetacion-2260', '2260', 'Dunas con vegetación esclerófila del Cisto-Lavanduletalia', 'Dunas', 'Matorral mediterráneo instalado sobre arenas ya fijadas, normalmente algo tierra adentro: jaras, jaguarzos, romero, lavandas, tomillos y enebros sobre suelo arenoso. Las hojas son duras o están cubiertas de pelillos, la defensa habitual contra el sol y la falta de agua, y muchas desprenden aroma al rozarlas. Es la etapa más madura y estable del sistema dunar, la última antes del bosque.', 0, 37.774627, -0.742206, '#66cdaa', '{"type":"Polygon","coordinates":[[[-0.743675,37.77668],[-0.743567,37.77649],[-0.743483,37.776333],[-0.743456,37.776132],[-0.743445,37.775957],[-0.743007,37.775884],[-0.742889,37.776024],[-0.742703,37.776104],[-0.742562,37.776076],[-0.742391,37.776053],[-0.74236,37.775774],[-0.741862,37.775628],[-0.742011,37.775551],[-0.74242,37.775653],[-0.743011,37.775761],[-0.743036,37.775484],[-0.743056,37.775374],[-0.743077,37.775193],[-0.743212,37.775103],[-0.743155,37.774746],[-0.743243,37.774639],[-0.743049,37.773701],[-0.742992,37.773448],[-0.742897,37.773448],[-0.742781,37.773415],[-0.742651,37.773369],[-0.742522,37.773288],[-0.742435,37.773219],[-0.74232,37.773104],[-0.742234,37.773035],[-0.742118,37.772978],[-0.742003,37.77292],[-0.741888,37.772852],[-0.741846,37.772827],[-0.741834,37.772819],[-0.741686,37.772849],[-0.741645,37.772818],[-0.741397,37.772817],[-0.741373,37.77279],[-0.741262,37.772778],[-0.741101,37.77276],[-0.741039,37.772632],[-0.740915,37.772559],[-0.7408,37.77249],[-0.740767,37.772421],[-0.740615,37.772357],[-0.740551,37.772295],[-0.740539,37.772224],[-0.740479,37.772171],[-0.740466,37.772142],[-0.740389,37.772127],[-0.740292,37.772113],[-0.740213,37.772215],[-0.740128,37.772452],[-0.740339,37.772654],[-0.740387,37.772681],[-0.740557,37.772699],[-0.740782,37.772667],[-0.740737,37.772793],[-0.740681,37.772989],[-0.74069,37.773042],[-0.740732,37.773103],[-0.740745,37.773128],[-0.74081,37.773167],[-0.740866,37.773216],[