    SELECT 'galerias-y-matorrales-92D0', '92D0', 'Galerías y matorrales ribereños termomediterráneos (Nerio-Tamaricetea)', 'Ribera', 'La vegetación leñosa de ramblas, arroyos y ríos de caudal irregular, que unos meses llevan agua y otros son un lecho de piedras: adelfares y tarayales. La adelfa (Nerium oleander), de hojas coriáceas y flores rosas, y los tarays (Tamarix), de ramillas finas y flores en espiga, resisten tanto las avenidas violentas como meses de sequía. Toda la adelfa es muy tóxica, incluidas hojas y ramas secas.', 0, 37.702303, -0.854163, '#2e8b57', '{"type":"MultiPolygon","coordinates":[[[[-0.863015,37.707438],[-0.862973,37.707244],[-0.862917,37.707072],[-0.862861,37.706886],[-0.862819,37.706772],[-0.862747,37.706656],[-0.862661,37.706576],[-0.862561,37.706495],[-0.862418,37.706425],[-0.862216,37.706356],[-0.862072,37.706311],[-0.861856,37.706216],[-0.861712,37.706182],[-0.861612,37.706135],[-0.861468,37.706065],[-0.861353,37.706032],[-0.861195,37.705961],[-0.861109,37.705881],[-0.861037,37.705787],[-0.860966,37.705684],[-0.86088,37.70557],[-0.860795,37.705431],[-0.860738,37.705329],[-0.860667,37.705201],[-0.860596,37.705063],[-0.860539,37.704902],[-0.860497,37.704752],[-0.860498,37.704604],[-0.860499,37.704444],[-0.860501,37.704284],[-0.860502,37.704158],[-0.860503,37.70402],[-0.860533,37.703906],[-0.860534,37.703766],[-0.860564,37.703618],[-0.860565,37.703447],[-0.860595,37.703296],[-0.860625,37.703159],[-0.860698,37.702987],[-0.860772,37.702793],[-0.860773,37.702599],[-0.860775,37.702403],[-0.860747,37.70222],[-0.860662,37.702058],[-0.860518,37.701988],[-0.860418,37.701908],[-0.86039,37.701794],[-0.86039,37.701702],[-0.860392,37.701587],[-0.860479,37.701427],[-0.860595,37.70137],[-0.860697,37.701313],[-0.860798,37.701268],[-0.860928,37.701212],[-0.861059,37.701119],[-0.861218,37.701086],[-0.861362,37.700997],[-0.861463,37.700951],[-0.861594,37.700881],[-0.861739,37.700769],[-0.861841,37.700699],[-0.861942,37.70062],[-0.862058,37.700529],[-0.862131