    SELECT 'pendientes-rocosas-siliceas-8220', '8220', 'Pendientes rocosas silíceas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca silícea —volcánica, granítica o de pizarra— donde la vegetación no arraiga en el suelo sino dentro de las grietas. Es el hermano ácido del roquedo calizo: las mismas plantas de raíz larga y crecimiento lentísimo agarradas a la fisura, pero sobre una roca sin cal, que selecciona especies distintas y a menudo mucho más raras. En el litoral mediterráneo aparece de forma muy puntual, allí donde asoma un afloramiento volcánico entre terrenos calizos.', 0, 37.687392, -0.843251, '#8b5e34', '{"type":"Polygon","coordinates":[[[-0.84643,37.687768],[-0.846334,37.687277],[-0.846332,37.687264],[-0.846283,37.686752],[-0.846283,37.686751],[-0.846238,37.686284],[-0.846232,37.686201],[-0.846223,37.686077],[-0.845899,37.685517],[-0.845644,37.685068],[-0.845081,37.684738],[-0.844427,37.684692],[-0.843824,37.684668],[-0.843261,37.684682],[-0.842712,37.684681],[-0.842493,37.68479],[-0.84174,37.685387],[-0.841151,37.685878],[-0.840735,37.686247],[-0.839917,37.686522],[-0.839581,37.687073],[-0.839394,37.687459],[-0.83928,37.687744],[-0.839353,37.68776],[-0.839497,37.687783],[-0.839613,37.687783],[-0.839742,37.687783],[-0.839843,37.687841],[-0.839944,37.687897],[-0.840002,37.688002],[-0.840016,37.688103],[-0.840016,37.688196],[-0.839957,37.688449],[-0.839972,37.688506],[-0.840044,37.688597],[-0.840043,37.68869],[-0.840115,37.688792],[-0.840217,37.688873],[-0.840317,37.68894],[-0.840404,37.689091],[-0.840417,37.689181],[-0.840475,37.689263],[-0.840562,37.689344],[-0.840626,37.68941],[-0.840742,37.689516],[-0.840762,37.689533],[-0.8409,37.689498],[-0.841017,37.689474],[-0.841091,37.689477],[-0.84149,37.689536],[-0.841675,37.689569],[-0.841767,37.689602],[-0.841854,37.689662],[-0.841913,37.689747],[-0.841918,37.689754],[-0.842029,37.689905],[-0.842046,37.689905],[-0.842176,37.689939],[-0.842274,37.689994],[-0.842421,37.689986],[-0.842521,37.6