    SELECT 'vegetacion-anual-sobre-1210', '1210', 'Vegetación anual sobre desechos marinos acumulados', 'Litoral', 'La primera línea de vegetación de una playa: plantas anuales que germinan sobre los restos que deja la marea, aprovechando el poco alimento y la humedad que guarda esa franja de algas y madera. Son hierbas carnosas de vida corta, como el rábano de mar (Cakile maritima) o la barrilla pinchosa (Salsola kali), que completan su ciclo en una sola temporada. Desaparece por completo donde se limpia la arena con maquinaria.', 0, 37.660511, -0.808056, '#6b8e23', '{"type":"Polygon","coordinates":[[[-0.815204,37.666133],[-0.815202,37.666063],[-0.815162,37.665999],[-0.813948,37.664835],[-0.812784,37.66372],[-0.810139,37.661788],[-0.80968,37.661453],[-0.806113,37.658919],[-0.802958,37.656842],[-0.799216,37.655377],[-0.798812,37.65521],[-0.798748,37.655184],[-0.79824,37.654974],[-0.797729,37.654763],[-0.797534,37.655037],[-0.798056,37.655252],[-0.798993,37.655639],[-0.799023,37.655667],[-0.80274,37.657108],[-0.805854,37.659158],[-0.809414,37.661686],[-0.81099,37.662838],[-0.811081,37.662905],[-0.811193,37.662986],[-0.811314,37.663073],[-0.811412,37.663145],[-0.811584,37.66327],[-0.811711,37.663387],[-0.811812,37.663479],[-0.811927,37.66356],[-0.812056,37.66365],[-0.812268,37.663769],[-0.812496,37.663936],[-0.814238,37.665607],[-0.814857,37.666201],[-0.814922,37.666243],[-0.815001,37.666257],[-0.815009,37.666258],[-0.815096,37.666241],[-0.815166,37.666198],[-0.815204,37.666133]]]}', NULL, '["1210"]', '["Salsolo kali-Cakiletum aegyptiacae Costa & Mansanet 1981"]', 'anadido_desde_oficial', NULL, NULL, NULL, NULL, NULL, NULL, NULL
