    SELECT 'dunas-moviles-embrionarias-2110', '2110', 'Dunas móviles embrionarias', 'Dunas', 'El primer relieve de arena de la playa, de apenas unos decímetros, que se forma donde una planta rastrera frena el viento y la arena se deposita a su alrededor. La construyen la grama de mar (Elymus farctus) y la juncia marina, capaces de crecer hacia arriba a medida que quedan enterradas. Es la duna naciente: si se pisa o se allana, todo el cordón dunar que hay detrás se queda sin recambio.', 0, 37.638329, -0.709708, '#6b8e23', '{"type":"MultiPolygon","coordinates":[[[[-0.815204,37.666133],[-0.815202,37.666063],[-0.815162,37.665999],[-0.813948,37.664835],[-0.812784,37.66372],[-0.810139,37.661788],[-0.80968,37.661453],[-0.806113,37.658919],[-0.802958,37.656842],[-0.799216,37.655377],[-0.798812,37.65521],[-0.798748,37.655184],[-0.79824,37.654974],[-0.797729,37.654763],[-0.797534,37.655037],[-0.798056,37.655252],[-0.798993,37.655639],[-0.799023,37.655667],[-0.80274,37.657108],[-0.805854,37.659158],[-0.809414,37.661686],[-0.81099,37.662838],[-0.811081,37.662905],[-0.811193,37.662986],[-0.811314,37.663073],[-0.811412,37.663145],[-0.811584,37.66327],[-0.811711,37.663387],[-0.811812,37.663479],[-0.811927,37.66356],[-0.812056,37.66365],[-0.812268,37.663769],[-0.812496,37.663936],[-0.814238,37.665607],[-0.814857,37.666201],[-0.814922,37.666243],[-0.815001,37.666257],[-0.815009,37.666258],[-0.815096,37.666241],[-0.815166,37.666198],[-0.815204,37.666133]]],[[[-0.712279,37.638251],[-0.712268,37.638158],[-0.71224,37.638054],[-0.71224,37.637942],[-0.712183,37.637837],[-0.712169,37.637735],[-0.712127,37.637619],[-0.712083,37.637483],[-0.712027,37.637253],[-0.711955,37.637127],[-0.711898,37.637036],[-0.711826,37.636956],[-0.711769,37.636876],[-0.711697,37.636796],[-0.711626,37.636704],[-0.711539,37.636612],[-0.71141,37.636531],[-0.711266,37.636497],[-0.711151,37.636463],[-0.710978,37.636462],[-0.710848,37.636461],[-0.71069,37.636483],[-0.710589,37.636565],[-0.710488,37.63661],[-0.710329,3