    SELECT 'zonas-subestepicas-de-6220', '6220', 'Zonas subestépicas de gramíneas y anuales del Thero-Brachypodietea', 'Pastos', 'Pastizales secos en los que conviven gramíneas vivaces de mata dura, como el lastón (Brachypodium retusum) o el esparto, con una multitud de plantas anuales diminutas que nacen con las lluvias y se secan antes del verano. En agosto parecen un erial pardo; en abril pueden reunir cuarenta especies distintas en un metro cuadrado. Esa riqueza escondida es la razón de que sea un hábitat prioritario.', 1, 37.620864, -0.801616, '#66cdaa', '{"type":"MultiPolygon","coordinates":[[[[-0.835405,37.636598],[-0.835402,37.635638],[-0.8351,37.635389],[-0.834765,37.634958],[-0.834594,37.634662],[-0.834547,37.634149],[-0.834542,37.633975],[-0.834253,37.633783],[-0.834069,37.633316],[-0.833807,37.632926],[-0.832648,37.632771],[-0.832274,37.63255],[-0.831772,37.632931],[-0.831404,37.633465],[-0.8312,37.63372],[-0.831209,37.63402],[-0.831188,37.634317],[-0.830662,37.63465],[-0.830173,37.634835],[-0.828839,37.634078],[-0.828887,37.633793],[-0.828907,37.633507],[-0.828585,37.633357],[-0.827957,37.633248],[-0.827409,37.633042],[-0.826818,37.632811],[-0.826511,37.63267],[-0.826001,37.632316],[-0.825738,37.631502],[-0.825436,37.631075],[-0.825156,37.630937],[-0.824881,37.630959],[-0.824483,37.631299],[-0.824261,37.631806],[-0.824087,37.632039],[-0.823976,37.632184],[-0.823674,37.632169],[-0.823296,37.632223],[-0.822799,37.632326],[-0.822594,37.632582],[-0.822577,37.633041],[-0.822602,37.633731],[-0.822751,37.634092],[-0.823111,37.634544],[-0.823617,37.635162],[-0.824047,37.635422],[-0.824121,37.635816],[-0.823639,37.636115],[-0.823485,37.636475],[-0.823575,37.637065],[-0.82402,37.637522],[-0.824187,37.637838],[-0.824273,37.638049],[-0.824452,37.638606],[-0.824484,37.638986],[-0.824587,37.639382],[-0.825002,37.639446],[-0.825464,37.639224],[-0.826687,37.639265],[-0.827057,37.639544],[-0.828191,37.640271],[-0.828755,37.640466],[-0.829501,37.640315],[-0.830305,37.639