    SELECT 'prados-calcareos-carsticos-6110', '6110', 'Prados calcáreos cársticos o basófilos del Alysso-Sedion albi', 'Pastos', 'Pastos abiertos sobre repisas y lanchas de roca caliza con apenas un dedo de tierra encima. Ahí solo prosperan plantas crasas de hojas gordas, como las uñas de gato (Sedum), y hierbas anuales minúsculas que nacen, florecen y mueren entre febrero y mayo. Ocupa superficies muy pequeñas y depende de que el suelo siga siendo escaso: en cuanto se acumula tierra, otras plantas lo desplazan.', 1, 37.660178, -0.737108, '#9acd32', '{"type":"Polygon","coordinates":[[[-0.740023,37.660917],[-0.739912,37.660428],[-0.739735,37.660077],[-0.739626,37.659773],[-0.739531,37.659677],[-0.739471,37.659295],[-0.739591,37.659025],[-0.739348,37.658786],[-0.73896,37.658767],[-0.738547,37.65868],[-0.737599,37.658378],[-0.737418,37.658321],[-0.7371,37.65827],[-0.736653,37.658198],[-0.736603,37.658218],[-0.736541,37.658217],[-0.736409,37.658218],[-0.73631,37.658224],[-0.736255,37.658229],[-0.736182,37.658196],[-0.736124,37.658192],[-0.736066,37.658156],[-0.735939,37.658141],[-0.735901,37.658161],[-0.735811,37.658124],[-0.735749,37.658123],[-0.735705,37.658122],[-0.735648,37.658168],[-0.735571,37.65819],[-0.735515,37.658229],[-0.735465,37.658304],[-0.735462,37.658377],[-0.735499,37.658494],[-0.735493,37.658561],[-0.735499,37.658608],[-0.735535,37.658641],[-0.73553,37.658807],[-0.735512,37.658905],[-0.735539,37.65899],[-0.735578,37.659046],[-0.735575,37.659119],[-0.735574,37.65916],[-0.735599,37.659198],[-0.735617,37.65933],[-0.735621,37.659426],[-0.735576,37.659526],[-0.735551,37.659542],[-0.735561,37.659568],[-0.735574,37.659591],[-0.735578,37.659608],[-0.735569,37.659634],[-0.735539,37.659673],[-0.735532,37.659705],[-0.735531,37.659738],[-0.735553,37.659763],[-0.735542,37.659853],[-0.735519,37.659911],[-0.735441,37.659979],[-0.73543,37.660008],[-0.735439,37.660038],[-0.735443,37.660062],[-0.735391,37.660122],[-0.73537,37.660145],[-0.735349,37.660229],[-0.735318,37.