    SELECT 'bosques-de-tetraclinis-9570', '9570', 'Bosques de Tetraclinis articulata', 'Bosque', 'Bosques de ciprés de Cartagena (Tetraclinis articulata), una conífera norteafricana cuyas únicas poblaciones europeas están en el sureste ibérico. Tiene ramillas articuladas y aplanadas y conos leñosos de cuatro valvas que se abren como una flor de madera, y rebrota de cepa después de un incendio, cosa rara entre las coníferas. Su rareza y su área diminuta explican que sea un hábitat prioritario.', 1, 37.619649, -0.801191, '#cd853f', '{"type":"MultiPolygon","coordinates":[[[[-0.806548,37.620893],[-0.80646,37.620681],[-0.806235,37.620432],[-0.806123,37.620272],[-0.806096,37.620234],[-0.805965,37.619989],[-0.805839,37.619871],[-0.805607,37.619518],[-0.805608,37.619503],[-0.805608,37.6195],[-0.805612,37.619437],[-0.805629,37.619379],[-0.805608,37.619263],[-0.805595,37.619158],[-0.805582,37.619127],[-0.80558,37.619108],[-0.805575,37.619059],[-0.805598,37.618945],[-0.805603,37.618842],[-0.805585,37.618734],[-0.805543,37.618578],[-0.80554,37.618551],[-0.805455,37.618492],[-0.80534,37.618413],[-0.805225,37.618343],[-0.805124,37.618274],[-0.805009,37.618206],[-0.804923,37.618137],[-0.804794,37.618022],[-0.804722,37.617942],[-0.804635,37.61785],[-0.804535,37.617724],[-0.804449,37.617633],[-0.804377,37.61753],[-0.804277,37.61746],[-0.804205,37.61738],[-0.804104,37.617288],[-0.804004,37.617185],[-0.803903,37.617095],[-0.803832,37.617015],[-0.803745,37.616923],[-0.803645,37.616795],[-0.803587,37.616715],[-0.803501,37.616624],[-0.803429,37.616543],[-0.803343,37.61644],[-0.803257,37.616337],[-0.803156,37.616234],[-0.803041,37.616097],[-0.802941,37.615982],[-0.802826,37.615845],[-0.802754,37.615742],[-0.802683,37.615662],[-0.802611,37.615582],[-0.802539,37.615502],[-0.802467,37.615422],[-0.802395,37.615341],[-0.802323,37.61525],[-0.802266,37.615159],[-0.80218,37.615067],[-0.802123,37.614987],[-0.802036,37.614884],[-0.801964,37.614804],[-0.801892,37.614724],[-0.801774,37.614608],[-0.80