    SELECT 'dunas-con-cespedes-2230', '2230', 'Dunas con céspedes del Malcomietalia', 'Dunas', 'Claros de arena entre el matorral dunar en los que, tras las lluvias, germina un césped efímero de plantas diminutas que florecen y se secan en pocas semanas. Pasan el resto del año como semilla enterrada, de modo que durante casi todo el verano el sitio parece arena vacía. Es un hábitat que solo se ve entero unas semanas al año, y por eso se destruye sin que nadie note que había algo.', 0, 37.638329, -0.709708, '#2e8b57', '{"type":"Polygon","coordinates":[[[-0.712279,37.638251],[-0.712268,37.638158],[-0.71224,37.638054],[-0.71224,37.637942],[-0.712183,37.637837],[-0.712169,37.637735],[-0.712127,37.637619],[-0.712083,37.637483],[-0.712055,37.637368],[-0.712027,37.637253],[-0.711955,37.637127],[-0.711898,37.637036],[-0.711826,37.636956],[-0.711769,37.636876],[-0.711697,37.636796],[-0.711626,37.636704],[-0.711539,37.636612],[-0.71141,37.636531],[-0.711266,37.636497],[-0.711151,37.636463],[-0.710978,37.636462],[-0.710848,37.636461],[-0.71069,37.636483],[-0.710589,37.636565],[-0.710488,37.63661],[-0.710329,37.636701],[-0.710213,37.636746],[-0.710069,37.636802],[-0.709911,37.636826],[-0.709795,37.636826],[-0.709637,37.636825],[-0.709478,37.636825],[-0.70932,37.636801],[-0.709176,37.636756],[-0.708989,37.636698],[-0.708845,37.636675],[-0.708716,37.636674],[-0.708709,37.636677],[-0.708704,37.636679],[-0.708653,37.636701],[-0.708526,37.636754],[-0.708344,37.636747],[-0.708282,37.636765],[-0.708139,37.636832],[-0.708008,37.636902],[-0.707893,37.636947],[-0.707778,37.637003],[-0.707633,37.637073],[-0.707518,37.637095],[-0.707359,37.637142],[-0.7072,37.637231],[-0.70707,37.637255],[-0.706955,37.637334],[-0.706868,37.637447],[-0.706868,37.637551],[-0.706867,37.637677],[-0.70691,37.637791],[-0.706967,37.637895],[-0.707039,37.637998],[-0.707125,37.638135],[-0.707196,37.638227],[-0.707297,37.638307],[-0.707411,37.638388],[-0.707569,37.638549],[-0.70767,37.638616],[-0.707785,37.63872],[-