    SELECT 'Alhucema', 'Lavandula multifida', 'flora', 'Mata aromática', 'Matorral seco, ribazos y bordes soleados de clima cálido', 'Alhucema de hojas muy divididas, casi como las de un helecho, y aspecto grisáceo. Florece durante buena parte del año en espigas azul violeta rematadas por dos brácteas alargadas. Su olor es más resinoso y menos dulce que el del espliego cultivado.', NULL, 'Hojas finamente divididas, de aspecto plumoso; Espigas azul violeta con dos brácteas en la punta; Aroma resinoso e intenso al frotar', 'Casi todo el año, con máximo en primavera y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lavandula_multifida.jpg?width=1280', 'Laitche (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-21); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Lavandula', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 5547, 3891203, 4, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sosa fina', 'Suaeda vera', 'flora', 'Mata', 'Bordes de saladar y suelos salinos algo más secos y elevados', 'Mata leñosa de hojas carnosas, cilíndricas y de un verde azulado, que ocupa la orla algo más alta y seca del saladar. Se diferencia de sus vecinas en que sí tiene hojas bien visibles y no tallos articulados. Sus flores son minúsculas y verdosas, en las axilas de las hojas.', NULL, 'Hojas carnosas y cilíndricas, verde azuladas; Base leñosa y ramificada, no herbácea; En la parte más seca y alta del saladar', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Suaeda_vera.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (10 hábitats; barrido de 2026-08-21); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Suaeda', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 8507, 6035538, 4, NULL, NULL, NULL
