    SELECT 'Orgaza', 'Atriplex glauca', 'flora', 'Mata', 'Matorrales halo-nitrófilos', 'Mata baja y extendida, de hojas pequeñas, grisáceas y cubiertas de escamas harinosas que reflejan la luz. Marca los suelos con sal y exceso de nitrógeno, como los antiguos apriscos. Sus frutos van encerrados entre dos valvas endurecidas.', NULL, 'Hojas pequeñas, grises y harinosas al tacto; Porte bajo y muy extendido, casi tendido; Frutos entre dos valvas duras y dentadas', 'Verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/611378691/original.jpg', 'Michael Bakker Paiva (CC BY 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (10 hábitats; barrido de 2026-08-21); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Atriplex', 'LC', NULL, 'No incluida en el LESRPE; característica de matorrales halonitrófilos (HIC 1430)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 2639, 7501008, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cosentinia vellea', 'Cosentinia vellea', 'flora', 'Helecho', 'Grietas de roquedos secos y soleados, paredones y pedregales', 'Helecho pequeño cubierto por completo de una densa lana parda que le da aspecto afieltrado y le permite sobrevivir en roca seca y al sol. En sequía se enrolla sobre sí mismo hasta parecer muerto, y se despliega en cuanto llueve.', NULL, 'Frondes cubiertas de lana parda, aspecto afieltrado; Se enrolla en verano y revive con la lluvia; En roca seca y soleada, no en umbrías húmedas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cosentinia_vellea_kz02.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-21); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Polypodiopsida', 'Polypodiales', 'Pteridaceae', 'Cosentinia', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 3758, 7335582, 3, NULL, NULL, NULL
