    SELECT 'Taray', 'Tamarix africana', 'flora', 'Árbol', 'Saladar junto a la playa del Sombrerico', 'Arbusto o arbolillo que forma los bosquetes de taray de mayor biomasa de la zona, como el rodal junto a la playa del Sombrerico.', NULL, 'Ramas finas y flexibles; Flores rosadas en espigas; Forma bosquetes junto a saladares', 'Primavera-verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tamarix_africana.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (8 hábitats; barrido de 2026-08-21); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Tamaricaceae', 'Tamarix', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 8547, 2874702, 1, NULL, NULL, NULL
