    UNION ALL
    SELECT 'Gaviota sombría', 'Larus fuscus', 'fauna', 'Ave marina', 'Costas, puertos, playas y vertederos, sobre todo en invierno', 'Gaviota grande de dorso gris oscuro o casi negro y patas amarillas, que cría en el norte de Europa e inverna en gran número en las costas ibéricas. Se mezcla con la patiamarilla, de la que se distingue por el manto mucho más oscuro y el porte algo más estilizado.', NULL, 'Manto gris pizarra oscuro, mucho más que en la patiamarilla; Patas amarillas y pico amarillo con mancha roja; Presente sobre todo en invierno, en bandos mixtos', 'Otoño e invierno', 'https://commons.wikimedia.org/wiki/Special:FilePath/Larus-fuscus-taxbox.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 36 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población en concentración, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Charadriiformes', 'Laridae', 'Larus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LC — Preocupación menor (Lista Roja española, 2004)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 14057, 2481174, 36, 'ES0000260', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Zorzal común', 'Turdus philomelos', 'fauna', 'Ave', NULL, 'Se trata de un zorzal de tamaño medio, con las regiones dorsales de un color pardo algo más cálido que el del zorzal charlo. Las partes inferiores presentan tonos claros, blanquecinos en el vientre y de un color ocre amarillento en el pecho, y aparecen profusamente tachonadas por motas en forma de cuña que, en la zona del cuello, se ordenan para dar lugar a una fina bigotera. Suele desplazarse por el suelo, aunque se posa en la parte más alta de arbustos y árboles para cantar. Su vuelo, rápido y algo espasmódico, permite observar la característica coloración herrumbrosa de su zona axilar, que facilita su diferenciación de otros zorzales.', NULL, NULL, 'Octubre a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9F%D0%B5%D0%B2%D1%87%D0%B8%D0%B9_%D0%B4%D1%80%D0%BE%D0%B7%D0%B4_%D0%BD%D0%B0_%D0%BF%D0%B5%D0%BD%D1%8C%D0%BA%D0%B5_(Turdus_philomelos)%2C_%D0%91%D0%B8%D1%82%D1%86%D0%B5%D0%B2%D1%81%D0%BA%D0%B8%D0%B9_%D0%BB%D0%B5%D1%81.jpg?width=1280', 'Dion Art (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 36 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Turdidae', 'Turdus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'NE — No evaluada (Lista Roja española, 2004)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11976, 7901064, 36, NULL, NULL, NULL
    UNION ALL
    SELECT 'Garza', 'Ardea purpurea', 'fauna', 'Ave acuática', 'Zonas húmedas con vegetación palustre', 'Los individuos adultos de garza imperial —muy similares en ambos sexos; la hembra, algo menor— lucen durante el periodo reproductor un vistoso diseño a base de tonos castaños, púrpuras y grisáceos. En el conjunto destacan las bandas longitudinales del cuello, negras y blancas, que se prolongan en unas largas plumas moteadas, y el capirote negruzco con irisaciones verdosas, del que parten un par de plumas oscuras. La parte inferior de las alas presenta una coloración muy oscura, en tanto que en los hombros dominan los tintes vinosos con reflejos purpúreos. Los jóvenes muestran una coloración menos contrastada, sin las líneas del cuello y con un aspecto general marronáceo. La garza imperial es un ave muy esbelta, con una silueta extraordinariamente estilizada, que en vuelo adopta la postura característica de las ardeidas: cuello recogido, alas curvadas y patas estiradas sobresaliendo por debajo del extremo de la cola. Aunque resulta bastante similar a la garza real, el menor tamaño y la tonalidad general más oscura de la imperial facilitan su identificación, tanto posada como en vuelo.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a septiembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/2010-kabini-purple-heron.jpg?width=1280', 'Yathin S Krishnappa (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF confirma su presencia con 35 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población en concentración, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Pelecaniformes', 'Ardeidae', 'Ardea', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LC — Preocupación menor (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 12041, 2480934, 35, 'ES0000260', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Ruiseñor común', 'Luscinia megarhynchos', 'fauna', 'Ave', 'Pisos bioclimáticos termo,meso,supramediterráneos,matorrales,sotos densos,montes bajos, jardines...', 'Ave estilizada, de pico fino y cola larga. Hembras y machos son iguales. Su manto y sus alas presentan un color pardo ocráceo uniforme, excepto en la cola, que posee un distintivo tono pardo rojizo. Las partes inferiores, mucho más claras, tienen color blanco crema. Este pájaro, muy escondidizo, rara vez abandona la protección de la espesura de la vegetación, pero resulta muy fácil de detectar por su inconfundible canto, muy sonoro, emitido incansablemente durante el día y la noche. Los jóvenes volantones, previamente a la muda parcial de su plumaje que tiene lugar antes de que comience la migración, exhiben un plumaje pardo que muestra plumas manchadas en su extremo con motas amarillentas. Los adultos se pueden confundir con carriceros comunes y ruiseñores bastardos, con los que a veces conviven en malezas ribereñas. Sin embargo, los carriceros presentan un tono ocre más pálido y amarillento, y carecen de la cola rojiza que luce el ruiseñor común. Lo mismo sucede con el ruiseñor bastardo, que además tiene una conspicua línea blanca sobre el ojo y posee unas alas y una cola cortas y redondeadas.', NULL, NULL, 'Abril a septiembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Luscinia_megarhynchos_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 35 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Luscinia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11701, 7660710, 35, NULL, NULL, NULL
    UNION ALL
    SELECT 'Avión zapador', 'Riparia riparia', 'fauna', 'Ave', 'Cría:en colonias excadas en taludes arenosos junto a ríos o lagos,muros.Dormideros en carrizales', 'Se trata del menor de nuestros aviones y golondrinas, aunque sólo es ligeramente más pequeño que el resto. Exhibe partes superiores de color pardo mate e inferiores blanquecinas, con límites netos entre ambas. Posee alas largas y apuntadas, que en vuelo destacan por su parte inferior y anterior más oscura. Tiene cola corta levemente ahorquillada, patas cortas sin emplumar, boca muy ancha, y pico corto, plano y negro. Resulta característica la ancha banda transversal de color pardo en el pecho. Ambos sexos son iguales. Los jóvenes, muy similares a los adultos, presentan la cabeza, el cuello y el bajo vientre teñidos de color cremarojizo, en tanto que las plumas del dorso y la cabeza muestran bordes pálidos. El avión zapador suele observarse en grupos, tanto en vuelo como posado en taludes y cables, y está más ligado al agua que otros aviones y golondrinas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a septiembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Riparia_riparia.jpg?width=1280', 'Axel Strauß (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 34 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población reproductora, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Hirundinidae', 'Riparia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 12097, 2489160, 34, 'ES0000260', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Garcilla cangrejera', 'Ardeola ralloides', 'fauna', 'Ave acuática', 'Estival (desde finales de abril), aunque también se da invernada en nuestro país', 'Garza de pequeño-mediano tamaño. El adulto reproductor tiene las partes superiores rosado-anaranjadas y las inferiores más blanquecinas. Del píleo le cuelgan largas plumas pardas, con raquis más pálido, que le dibujan una melena sobre el dorso. Su pico es azulado, con el extremo negro, y luce patas naranjas. El adulto no reproductor es mucho más parduzco, con toda la cabeza y el cuello repletos de estrías longitudinales blancas y pardas, patas amarillentas y pico naranja sucio. Los jóvenes son muy similares a los adultos no reproductores. En vuelo, la garcilla cangrejera se muestra muy pálida, ya que sus alas y cola son blancas, y el cuerpo y la cabeza rosados. Se localiza generalmente en aguazales abiertos, en orillas o en aguas someras.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Crabier_chevelu.jpg?width=1280', 'Pierre Dalous (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'GBIF confirma su presencia con 32 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población en concentración, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Pelecaniformes', 'Ardeidae', 'Ardeola', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'NT — Casi amenazada (Lista Roja española, 2004)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 12081, 2480906, 32, 'ES0000260', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Pito ibérico', 'Picus sharpei', 'fauna', 'Ave', NULL, 'Es un pájaro carpintero grande y robusto, de aspecto inconfundible, en cuyo plumaje dominan claramente los tonos verdosos, más intensos en las regiones dorsales, ligeramente grisáceos en las ventrales y con matices amarillentos en el obispillo. Carece de moteados y listas —salvo, tenuemente, en la región anal—, pero luce un llamativo patrón de coloración en la cabeza, donde el píleo es rojo y los ojos, amarillentos, aparecen enmarcados por un antifaz negro. Los machos y los jóvenes presentan una bigotera negra y roja, que es exclusivamente negra en las hembras. El plumaje juvenil se caracteriza por ser fuertemente moteado, especialmente en las partes inferiores, aunque, en conjunto, su coloración es más apagada que la del adulto, no presentan antifaz y poseen un iris más oscuro. Su vuelo es muy característico, con una trayectoria ondulatoria en la que el ave combina tramos en los que bate las alas con otros en que las pliega.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Iberian_Green_Woodpecker_(Pito_Ib%C3%A9rico)_(Picus_sharpei)_-_Torrevieja%2C_Spain_2024-02-04.jpg?width=1280', 'Ryan Hodnett (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 32 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %, que la cita como «Picus viridis»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Piciformes', 'Picidae', 'Picus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2020)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 33014, 9029556, 32, NULL, NULL, NULL
    UNION ALL
    SELECT 'Vencejo real', 'Tachymarptis melba', 'fauna', 'Ave', 'Nidos:Acantilados,cortados,marinos e interior.Hasta 1900m.Sustrato preferido calizo,...Edificaciones', 'Se trata del más grande y vistoso de los vencejos españoles. Presenta una silueta típica en forma de ballesta, cola corta y levemente ahorquillada, y alas muy largas y estrechas, de aleteos lentos. Posee pico corto, plano y con la boca muy ancha; patas emplumadas y extremadamente cortas, que le impiden posarse en el suelo; y pies pequeños y de fuertes garras, con los cuatro dedos dirigidos hacia delante. Muestra coloración general pardo oliva, más oscura en las alas, con dos destacadas áreas blancas en el vientre y la garganta, separadas ambas por un collar parduzco. Ambos sexos son iguales. Los jóvenes resultan muy similares a los adultos, aunque un poco más oscuros y con plumas ribeteadas de blanco. Esta ave pasa la mayor parte de su vida en el aire, por lo que casi siempre se la ve volando y agrupada, tanto en núcleos urbanos como en acantilados costeros y de interior.', NULL, NULL, 'Marzo a octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tachymarptis_melba_-Barcelona%2C_Spain_-flying-8.jpg?width=1280', 'Birdwatching Barcelona (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 32 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %, que la cita como «Apus melba»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Apodiformes', 'Apodidae', 'Tachymarptis', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 24459, 2477411, 32, NULL, NULL, NULL
    UNION ALL
    SELECT 'Curruca zarcera', 'Curruca communis', 'fauna', 'Ave', 'Linderos con arbustos y malezas espesas,cultivos, bosquetes, praderas y claros con setos de matorral', 'Curruca de mediano tamaño, de cola relativamente larga y con rectrices externas blancas. El macho presenta el dorso de color pardo, con la cabeza gris en plumaje de cría y parda durante el resto del año, las alas pardo-rojizas, la garganta blanca, y las partes inferiores blanquecinas y con tonos rosados. La hembra muestra tonalidades más apagadas, con la cabeza y el dorso más pardos, la garganta blanquecina y más apagada, y la zona ventral también blanquecina y sin los tonos ligeramente asalmonados del macho. Ambos sexos tienen las patas claras. Los adultos lucen un iris rojizo, que contrasta con un tenue anillo orbital claro.', NULL, NULL, 'Abril a octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_-_Rainbirder_-_Common_Whitethroat_(Sylvia_communis).jpg?width=1280', 'Steve Garvie from Dunfermline, Fife, Scotland (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 31 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %, que la cita como «Sylvia communis»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 80921, 2492943, 31, NULL, NULL, NULL
    UNION ALL
    SELECT 'Agachadiza chica', 'Lymnocryptes minimus', 'fauna', 'Ave limícola', NULL, 'Se trata de una limícola pequeña, de pico relativamente largo y de colores muy crípticos, que le permiten pasar inadvertida cuando se encuentra entre la maleza ribereña. Tiene un característico brillo verdoso en las escapulares, que aparece enmarcado por dos líneas longitudinales de color crema a cada lado del cuerpo, una en las plumas del manto y otra en las escapulares inferiores. Las regiones ventrales y el pecho son blancos, con la garganta estriada de marrón. En la cabeza presenta un doble listado por encima del ojo, aunque sin lista pileal clara. El adulto y el joven son prácticamente idénticos. En vuelo dispone la cola en forma de cuña y luce un plumaje bastante pardo, con las rémiges oscuras y un estrecho borde blanco en los extremos de las secundarias.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Octubre a abril', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lymnocryptes_minimus_(Marek_Szczepanek).jpg?width=1280', 'Marek Szczepanek (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 30 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población en concentración, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Charadriiformes', 'Scolopacidae', 'Lymnocryptes', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'DD — Datos insuficientes (Lista Roja española, 2004)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11738, 2481835, 30, 'ES0000260', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Calandrella rufescens', 'Calandrella rufescens', 'fauna', 'Ave esteparia', 'Saladares, estepas salinas, eriales y llanos áridos con vegetación rala', 'La alondra más pequeña de Europa, de plumaje pardo grisáceo y con el pecho finamente rayado de arriba abajo, sin las manchas laterales de su parienta. Vive ligada a los llanos más áridos y salinos, un hábitat en retroceso, y se camufla tan bien que suele verse solo al levantar el vuelo.', NULL, 'Rayado fino y extendido por todo el pecho; Muy pequeña y compacta, de aspecto grisáceo; Prefiere los llanos salinos y las estepas más áridas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Calandrella_rufescens_Canarias.jpg?width=1280', 'Calandrella_rufescens_-Canary_Islands_-Spain-8.jpg: Tony Hisgett de… (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 29 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Calandrella', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2022)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 33007, 2490682, 29, NULL, NULL, NULL
    UNION ALL
    SELECT 'Carricero tordal', 'Acrocephalus arundinaceus', 'fauna', 'Ave', 'Nidos:zonas palustres,carrizales espesos (Phragmites sp.),eneas (Typha sp.),espadañas.Masas de agua', 'Se trata de la especie más robusta entre los carriceros y carricerines. De tonos pardos uniformes, es similar al carricero común, aunque notablemente mayor y con el pico más grande. Presenta el dorso marrón rojizo o grisáceo, según la edad y el desgaste de la pluma, y tiene las partes inferiores de tonos pardo-amarillentos. Ambos sexos son iguales.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Abril a septiembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carricero_tordal.jpg?width=1280', 'Carles Pastor (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 24 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población reproductora, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Acrocephalidae', 'Acrocephalus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 10766, 2493128, 24, 'ES0000260', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Porrón europeo', 'Aythya ferina', 'fauna', 'Ave acuática', 'Según los datos de los últimos censos de invernantes es frecuente en muchos tipos de humedales, incluso en áreas periurbanas', 'Se trata de un pato buceador típico, de aspecto compacto, cola corta, fuertes patas y vuelo vibrante, que se desplaza por el agua con el cuerpo muy sumergido y la cola baja. El macho adulto en plumaje nupcial posee la popa y el pecho negros, el dorso, los flancos y el vientre grisáceos y la cabeza de color pardo rojizo; el pico es oscuro, aunque surcado por una banda transversal grisácea, y el ojo, rojo. En vuelo se ve bastante gris, con el pecho y la parte superior del dorso oscuros y la cabeza rojiza. La hembra, por su parte, resulta mucho más homogénea, con la popa y el pecho rojizos, el dorso, los flancos y el vientre grisáceos y la cabeza de color crema sucio; el ojo es oscuro y el pico, negruzco, con una estrecha faja pálida. El joven es muy similar a la hembra, pero más apagado, con más pardo y menos gris.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Male_pochard_reflection_in_evening.jpg?width=1280', 'Neil Phillips (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 24 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población en concentración, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Anseriformes', 'Anatidae', 'Aythya', 'VU — Vulnerable (Lista Roja mundial de la UICN, 2021)', 'NE — No evaluada (Lista Roja española, 2004)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11258, 2498255, 24, 'ES0000260', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Correlimos gordo', 'Calidris canutus', 'fauna', 'Ave limícola', NULL, 'Se trata de una limícola de talla pequeña, rechoncha, con patas relativamente cortas (de aproximadamente la anchura del cuerpo o menos) y pico negro bastante corto y ancho. El adulto en plumaje nupcial presenta la cara y las partes inferiores de color rojo acastañado, el píleo con densas estrías marrones, las plumas de las partes superiores oscuras con muescas anaranjadas y las cobertoras alares grises con márgenes pálidos. El adulto no reproductor luce un plumaje, en general, gris bastante uniforme, con el raquis de las plumas más oscuro y una delgada orla blanca, así como una destacada ceja pálida y estrías en los lados del pecho. El joven es similar al no reproductor, pero algo más amarillento y con un doble borde negro y blanco en las plumas de las partes superiores.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Abril, mayo, agosto, septiembre, octubre, noviembre, diciembre, enero', 'https://commons.wikimedia.org/wiki/Special:FilePath/Calidris_canutus_(summer).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 22 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población en concentración, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Charadriiformes', 'Scolopacidae', 'Calidris', 'NT — Casi amenazada (Lista Roja mundial de la UICN, 2018)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 10957, 2481765, 22, 'ES0000260', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Carraca europea', 'Coracias garrulus', 'fauna', 'Ave', 'Campos abiertos con arbolado disperso, ribazos y construcciones con huecos', 'Del tamaño de una paloma y de un azul turquesa intenso que sorprende al levantar el vuelo. Caza al acecho desde cables y postes, dejándose caer sobre saltamontes y escarabajos. Cría en huecos de árboles viejos y de edificios, de ahí que dependa de que queden árboles añosos y ruinas en el campo.', NULL, 'Azul turquesa que solo se aprecia bien cuando vuela; Espalda de color canela que contrasta con el azul; Posada quieta en cables, oteando el suelo', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/European_roller.jpg?width=1280', 'Christian Svane (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 21 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2: población en concentración, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Coraciiformes', 'Coraciidae', 'Coracias', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'VU — Vulnerable (Lista Roja española, 2004)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE; Ley 42/2007, Anexo IV', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 11339, 2475365, 21, 'ES0000260', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Halcón peregrino', 'Falco peregrinus', 'fauna', 'Ave rapaz', 'Cortados y áreas abiertas', 'Halcón robusto de alas puntiagudas y cola corta, capaz de superar los 300 km/h en el picado con que abate a otras aves en pleno vuelo. Se reconoce por la ancha bigotera negra que baja desde el ojo sobre un pecho claro y barrado.', NULL, 'Bigotera negra ancha bajo el ojo, como un casco; Silueta de ancla: alas puntiagudas y cola corta; Pecho claro con barrado fino en horizontal', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Falco_peregrinus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 21 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2, que la cita como «Falco peregrinus ([including pelegrinoides])»: población permanente, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Falconiformes', 'Falconidae', 'Falco', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'EN — En peligro (Lista Roja española, 2004)', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 11963, 2481047, 21, 'ES0000260', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Correlimos de Temminck', 'Calidris temminckii', 'fauna', 'Ave limícola', 'En paso e invernada: aguas dulces, lagunas, marismas, vegas,etc.Areas marinas litorales resguardadas', 'Es una limícola de reducido tamaño y de cuerpo bastante alargado, con el pico más bien pequeño y las patas más cortas que la altura del cuerpo. En todos los plumajes, la garganta y el pecho —muy oscuros— definen una especie de babero. Tiene las patas verdosas y el pico de color negro. El adulto en plumaje nupcial suele presentar las partes dorsales con una mezcla de plumas nuevas (oscuras, con bordes castaño claro) y otras correspondientes al plumaje invernal (grises, con el raquis apenas marcado); los lados del cuello y el pecho son de color ante, con finas estrías más oscuras, y las partes inferiores, blancas. El individuo no reproductor luce un gris uniforme no muy claro, con el pecho más grisáceo que el nupcial y sin estrías, mientras que el joven tiene el pecho levemente estriado y presenta las plumas de las partes superiores grises, con el raquis y una banda subapical oscuros y los bordes cremosos.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Julio, agosto, septiembre, octubre, noviembre, enero, febrero, marzo, abril, mayo', 'https://commons.wikimedia.org/wiki/Special:FilePath/Calidris_temminckii_2_(Marek_Szczepanek).jpg?width=1280', 'Marek Szczepanek (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 19 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Charadriiformes', 'Scolopacidae', 'Calidris', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LC — Preocupación menor (Lista Roja española, 1992)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 16333, 2481740, 19, NULL, NULL, NULL
    UNION ALL
    SELECT 'Grajilla occidental', 'Corvus monedula', 'fauna', 'Ave', NULL, 'Ave de tamaño más modesto que grajas y cornejas, la grajilla luce un plumaje muy oscuro, que a cierta distancia parece negro. Vista de cerca, sin embargo, se aprecia una cierta tonalidad grisácea en algunas regiones del cuerpo, especialmente en el pecho y en la nuca, que es de un bello color ceniciento. El iris es muy claro, de un azul pálido, casi blanco. Es habitual que las grajillas se organicen en ruidosos bandos que sobrevuelan las rocas y los viejos edificios o que menudean por campos y pastizales en busca de alimento.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/%D0%93%D0%B0%D0%BB%D0%BA%D0%B0_(Corvus_monedula)%2C_%D0%A6%D0%B0%D1%80%D0%B8%D1%86%D1%8B%D0%BD%D0%BE.jpg?width=1280', 'Dion Art (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 19 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Corvidae', 'Corvus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'NE — No evaluada (Lista Roja española, 2004)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11769, 6100954, 19, NULL, NULL, NULL
    UNION ALL
    SELECT 'Calamón', 'Porphyrio porphyrio', 'fauna', 'Ave acuática', NULL, 'El más grande de los rálidos europeos es un ave de buen tamaño y aspecto absolutamente inconfundible. Los ejemplares adultos lucen un plumaje de tonos azulados y violáceos con reflejos purpúreos, que se torna azul metálico en la cara, la parte anterior del cuello y la zona superior del pecho; las infracoberteras caudales, de color blanco puro, contrastan vivamente con el resto de la librea del ave, y son utilizadas por el calamón para expresar sus estados de ánimo y comunicarse con otros ejemplares. Las partes desprovistas de plumas se caracterizan también por su viva coloración, especialmente durante la época de celo, ya que tanto el pico —cónico y robusto— como el escudete frontal y las patas lucen un intenso color carmesí. Estas últimas, francamente singulares, reflejan su forma de vida; son considerablemente largas y aparecen rematadas por larguísimos dedos con gran capacidad prensil, que el ave emplea para manejar tallos, moverse entre las cañas y deambular por la vegetación flotante. Los calamones jóvenes no exhiben un plumaje tan espectacular como el de los adultos, ya que en ellos predominan los tonos azulados más bien grisáceos en el dorso y los blanquecinos en el vientre, en tanto que las zonas desnudas (patas, pico y escudete), aunque rojizas, no presentan la brillante coloración de las aves maduras. Este rálido —al igual que la generalidad de los componentes de la familia— es un volador bastante torpe; no obstante, se desplaza con soltura entre las cañas y prefiere escabullirse entre ellas en caso de alarma o peligro. Las escasas ocasiones en que vuela —por lo común no más de 15 o 20 metros— se desplaza con frecuentes aleteos de sus cortas alas, mientras mantiene colgando las patas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Purpurhuhn.jpg?width=1280', 'Andreas Trepte (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 19 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2, que la cita como «Porphyrio porphyrio porphyrio»: población reproductora; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Gruiformes', 'Rallidae', 'Porphyrio', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 12013, 2474416, 19, 'ES0000260', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
    UNION ALL
    SELECT 'Lúgano', 'Spinus spinus', 'fauna', 'Ave', 'Sus preferencias de hábitat van ligadas a sus requerimientos tróficos', 'Se trata de un ave pequeña, de pico corto y fino, que muestra cola corta y escotada cuando está cerrada. Su coloración puede recordar a la de verdecillos, verderones comunes y verderones serranos. Pero los lúganos se distinguen bien por la combinación de los siguientes caracteres: pequeño tamaño, manchas amarillas en alas y cola, y franjas amarillas en los “hombros” de las alas. Además, los machos tienen el capirote y la garganta negros. Es una especie gregaria que se mezcla con otras, sobre todo fringílidos como pardillos, pinzones vulgares, verdecillos, verderones serranos, pinzones reales, etc. Pero, a diferencia de la mayoría de los fringílidos, el lúgano también busca alimento en las ramas de árboles de ribera, siendo común observarlo en alisos, olmos y abedules.', NULL, NULL, 'Octubre a abril', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carduelis_Spinus_(55339970).jpeg?width=1280', 'Kobolt (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 18 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %, que la cita como «Carduelis spinus»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Fringillidae', 'Spinus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 33009, 6092830, 18, NULL, NULL, NULL
    UNION ALL
    SELECT 'Negrón común', 'Melanitta nigra', 'fauna', 'Ave acuática', 'Durante el invierno es una anátida es trictamente marina que utiliza zonas litorales de poca profundidad', 'Se trata de un pato marino de ancho pico, larga cola apuntada y plumaje muy oscuro. El macho adulto es completamente negro, a excepción de una porción del pico, que es anaranjada. En vuelo se ve muy oscuro, aunque con las primarias algo pálidas. La hembra es gris pardo muy oscuro, con las mejillas y parte del cuello de color marrón claro. El joven, aunque similar a la hembra, resulta ligeramente más oscuro; en vuelo ambos presentan las primarias algo más pálidas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Julio a marzo', 'https://commons.wikimedia.org/wiki/Special:FilePath/Melanitta_nigra_by_Henry_E._Dresser.jpg?width=1280', 'Henry Eeles Dresser (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 17 ocurrencias dentro del espacio (barrido de 2026-08-21); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2, que la cita como «Melanitta nigra (sensu stricto [excluding americana])»: población invernante, presente; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §2.1.2 (Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor») (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Paisaje Protegido «Espacios Abiertos e Islas del Mar Menor», que es el propio espacio: el volumen II le dedica un apartado con inventario propio (§2.1), distinto del de su ZEC ES6200006 (§1.1.2), y la tabla del §2 del volumen I mide sus 1.307,85 ha dentro del ámbito del plan, el 100 %; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Anseriformes', 'Anatidae', 'Melanitta', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'NE — No evaluada (Lista Roja española, 2004)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 13987, 2498247, 17, 'ES0000260', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000260","name":"Mar Menor","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000260 (Mar Menor), sección 3.2"}'
